<div class="contact-form-actions"><button class="contact-button contact-button-primary" <?= !$settings['enabled']?'disabled':'' ?>>Enviar correo con adjuntos</button><?php if(!$embedded): ?><a class="contact-button" href="<?= $e($source) ?>">Volver al documento</a><?php endif; ?></div></form>
<section class="contact-sheet"><h2>Últimos envíos de esta factura</h2><?php foreach($logs as $entry): ?><article class="email-log"><strong><?= $e($entry['recipient']) ?></strong><p><?= $e($entry['subject']) ?></p><p><?= $e($entry['created_at']) ?> · <?= $entry['status']==='sent'?'Aceptado por SMTP':($entry['status']==='sending'?'En proceso / pendiente de confirmación':'Resultado no confirmado') ?></p><p>Desde: <?= $e($entry['from_email']) ?></p><?php foreach(json_decode($entry['documents_json'],true,8,JSON_THROW_ON_ERROR) as $attachment): ?><small><?= $e($attachment['label']) ?> · PDF</small><?php endforeach; ?></article><?php endforeach; ?><?php if(!$logs): ?><p>Aún no hay envíos registrados desde este documento.</p><?php endif; ?></section>
